it('list skips a corrupt zstd session log instead of failing the whole listing', async () => {
  const absoluteRoot = await freshRoot()
  const ctx = new Context()
  await ctx.plugin(SessionStore)
  const fiber = await ctx.plugin(JsonlSessionPersistence, { root: absoluteRoot, compression: 'zstd' })
  // A healthy session, materialized through the real write path.
  const good = meta('good-session', '/work')
  await ctx.sessionPersistence.create(good)
  await ctx.sessionPersistence.append(good.id, [
