  // the listing must skip it instead of failing the entire host boot.
  const badId = SessionId('corrupt-session')
  const badPath = logPath(resolve(absoluteRoot), '/work', badId, 'zstd')
  await mkdir(dirname(badPath), { recursive: true })
  const corruptFrame = `${JSON.stringify(toHeaderLine(meta('corrupt-session', '/work')))}\n{"extra":"line"}\n`
  await writeFile(badPath, zstdCompressSync(Buffer.from(corruptFrame)))
  // Listing must neither throw nor surface the corrupt session.
  const sessions = await ctx.sessionPersistence.list()
  const ids = sessions.map(session => session.id)
  expect(ids).toContain(good.id)
  expect(ids).not.toContain(badId)
